bool SdlAudioBackend::load_movie(
    uint32_t key, DecodedAudio audio) {
    if (!available() || audio.samples.empty()) {
        return false;
    }
    std::scoped_lock lock(mutex_);
    Track& slot = movie_tracks_[key];
    slot.clip =
        std::make_shared<const DecodedAudio>(std::move(audio));
    slot.position = 0.0;
    slot.playback_rate = 1.0;
    slot.left_gain = 1.0;
    slot.right_gain = 1.0;
    slot.active = false;
    slot.bgm = false;
    slot.paused = false;
    return true;
}
